export function getDistrictColor(rank) {
  if (!rank) return '#1B2537';
  if (rank === 1) return '#38BDF8';
  if (rank === 2) return '#2DD4BF';
  if (rank === 3) return '#22D3EE';
  if (rank <= 5) return '#1D9FBF';
  if (rank <= 10) return '#1A6B8A';
  return '#1B2537';
}
